import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import datetime
import os

# Set plotting style
plt.style.use('default')
sns.set_theme(style="whitegrid")

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{img_str}"

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])
df['year'] = df['date'].dt.year
df['month'] = df['date'].dt.month

# 2. Calculate KPIs
avg_petrol = df['petrol_usd_liter'].mean()
corr_brent_petrol = df['brent_crude_usd'].corr(df['petrol_usd_liter'])
corr_brent_diesel = df['brent_crude_usd'].corr(df['diesel_usd_liter'])

# Subsidy effect
subsidy_means = df.groupby('subsidy_level')['petrol_usd_liter'].mean()
if 'High' in subsidy_means and 'Low' in subsidy_means:
    high_subsidy_price = subsidy_means['High']
    low_subsidy_price = subsidy_means['Low']
    subsidy_dampening_effect = ((low_subsidy_price - high_subsidy_price) / low_subsidy_price) * 100
else:
    subsidy_dampening_effect = 0

# Regional Price Spread (Average over the years of the max-min spread)
yearly_region_means = df.groupby(['year', 'region'])['petrol_usd_liter'].mean().unstack()
yearly_spread = yearly_region_means.max(axis=1) - yearly_region_means.min(axis=1)
avg_regional_spread = yearly_spread.mean()

# Tax by Income Level
tax_by_income = df.groupby('income_level')['tax_percentage'].mean()

# 3. Generate Charts

# Chart 1: Temporal Trends
fig1, ax1 = plt.subplots(figsize=(10, 5))
weekly_trends = df.groupby('date')[['petrol_usd_liter', 'diesel_usd_liter', 'brent_crude_usd']].mean()
# Scale brent crude (per barrel) to per liter approximation for visual alignment, 1 barrel = 158.987 liters
weekly_trends['brent_usd_liter'] = weekly_trends['brent_crude_usd'] / 158.987

ax1.plot(weekly_trends.index, weekly_trends['petrol_usd_liter'], label='Petrol (USD/L)', color='#1f77b4', linewidth=2)
ax1.plot(weekly_trends.index, weekly_trends['diesel_usd_liter'], label='Diesel (USD/L)', color='#ff7f0e', linewidth=2)
ax1.plot(weekly_trends.index, weekly_trends['brent_usd_liter'], label='Brent Crude (USD/L eq.)', color='#2ca02c', linestyle='--', linewidth=2)
ax1.set_title('Global Average Fuel Prices vs Brent Crude (2020-2026)', fontsize=14, fontweight='bold')
ax1.set_ylabel('Price (USD/Liter)')
ax1.set_xlabel('Date')
ax1.legend()
plt.tight_layout()
chart1_b64 = fig_to_base64(fig1)

# Chart 2: Regional Disparities
fig2, ax2 = plt.subplots(figsize=(10, 5))
sns.boxplot(x='region', y='petrol_usd_liter', data=df, ax=ax2, palette='Blues_r', order=df.groupby('region')['petrol_usd_liter'].median().sort_values(ascending=False).index)
ax2.set_title('Petrol Price Distribution by Region', fontsize=14, fontweight='bold')
ax2.set_ylabel('Petrol Price (USD/Liter)')
ax2.set_xlabel('Region')
plt.xticks(rotation=45)
plt.tight_layout()
chart2_b64 = fig_to_base64(fig2)

# Chart 3: Subsidy Impact
fig3, ax3 = plt.subplots(figsize=(10, 5))
subsidy_trends = df.groupby(['date', 'subsidy_level'])['petrol_usd_liter'].mean().unstack()
ax3.plot(subsidy_trends.index, subsidy_trends['Low'], label='Low Subsidy', color='#d62728', linewidth=2)
ax3.plot(subsidy_trends.index, subsidy_trends['High'], label='High Subsidy', color='#2ca02c', linewidth=2)
ax3.set_title('Average Petrol Price: High vs Low Subsidy', fontsize=14, fontweight='bold')
ax3.set_ylabel('Price (USD/Liter)')
ax3.set_xlabel('Date')
ax3.legend()
plt.tight_layout()
chart3_b64 = fig_to_base64(fig3)

# Chart 4: Income Level
fig4, ax4 = plt.subplots(figsize=(8, 5))
income_stats = df.groupby('income_level')[['petrol_usd_liter', 'tax_percentage']].mean().loc[['High', 'Middle', 'Low']]
ax4_2 = ax4.twinx()

bars = ax4.bar(income_stats.index, income_stats['petrol_usd_liter'], color='#aec7e8', width=0.4, label='Avg Petrol Price')
ax4.set_ylabel('Petrol Price (USD/Liter)', color='#1f77b4')
ax4.tick_params(axis='y', labelcolor='#1f77b4')

line = ax4_2.plot(income_stats.index, income_stats['tax_percentage'], color='#ff7f0e', marker='o', linewidth=2, label='Avg Tax %')
ax4_2.set_ylabel('Tax Percentage (%)', color='#ff7f0e')
ax4_2.tick_params(axis='y', labelcolor='#ff7f0e')

ax4.set_title('Petrol Price and Tax Percentage by Income Level', fontsize=14, fontweight='bold')
plt.tight_layout()
chart4_b64 = fig_to_base64(fig4)


